import {adFor,adFace} from './advertising-assets.js?v=55';
const PI=Math.PI;
export function lightbox(b,ad,x,y,z,w,h,ry=0){b.push(x,y,z,ry);b.box('metal',0,0,0,w+.10,h+.10,.19);b.box('white',0,0,.10,w+.025,h+.025,.035);adFace(b,ad,0,0,.123,w,h);b.pop();}
export function floodlights(b,w,y,z,count=3){for(let i=0;i<count;i++){const x=(i-(count-1)/2)*w/(count+.4);b.rod('metal',[x,y,z],[x,y+.10,z+.8],.025);b.box('dark',x,y+.12,z+.85,.38,.15,.23);b.plane('lamp',x,y+.145,z+.979,.29,.085);}}
export function roofBillboard(b,ad,w,roof,z){const h=w/(ad.kind==='poster'?2:24/7),cy=roof+1.1+h/2;b.push(0,0,z);b.box('steel',0,cy,0,w+.16,h+.16,.28);adFace(b,ad,0,cy,.151,w,h);for(const x of[-w*.34,w*.34]){b.box('concrete',x,roof+.13,-1.1,.62,.26,2.6);b.rod('steel',[x,roof+.26,0],[x,cy+h/2,0],.095);b.rod('steel',[x,roof+.26,-2.2],[x,cy+h*.34,0],.065);}for(let k=0;k<3;k++)b.box('metal',0,cy+(k-1)*h*.4,-.21,w,.07,.08);b.box('steel',0,roof+.70,.55,w+.65,.08,.84);floodlights(b,w,cy-h/2-.15,.12,4);b.pop();}
export function wallBanner(b,ad,x,y,z,w,h,ry=0){b.push(x,y,z,ry);b.box('steel',0,0,.01,w+.22,h+.14,.06);adFace(b,ad,0,0,.052,w,h);for(const sx of[-1,1]){for(let yy=-h/2;yy<=h/2+.02;yy+=2.5){b.rod('steel',[sx*w/2,yy,.045],[sx*(w/2+.20),yy,.005],.012);b.sphere('metal',sx*(w/2+.20),yy,.01,.026,.026,.025);}}b.box('metal',0,-h/2-.06,.01,w+.30,.10,.12);b.box('metal',0,h/2+.06,.01,w+.30,.10,.12);floodlights(b,w,-h/2-.16,.03,3);b.pop();}
export function bladeSign(b,ad,x,y,z,w=.70,h=2.10){b.push(x,y,z);for(const yy of[-h*.34,h*.34]){b.rod('metal',[0,yy,-.10],[0,yy,.90],.035);b.rod('metal',[0,yy+.30,-.10],[0,yy,.70],.023);}b.box('metal',0,0,.67,.16,h+.10,w+.10);adFace(b,ad,.092,0,.67,w,h,PI/2);adFace(b,ad,-.092,0,.67,w,h,-PI/2);b.pop();}
export function poleSign(b,ad,x,z,w=3.3,h=6.4,ry=0){b.push(x,0,z,ry);const y=2.5+h/2;for(const xx of[-w*.32,w*.32]){b.box('concrete',xx,.12,0,.72,.24,.9);b.rod('steel',[xx,.24,0],[xx,y+h/2,0],.095);b.circle(xx,0,.38);}b.box('metal',0,y,0,w+.16,h+.16,.30);adFace(b,ad,0,y,.166,w,h);adFace(b,ad,0,y,-.166,w,h,PI);b.pop();}
export function monumentSign(b,ad,x,z,w=3.4,ry=0){b.push(x,0,z,ry);b.box('travertine',0,.34,0,w+.35,.68,.66);b.box('metal',0,1.14,0,w,1.04,.24);adFace(b,ad,0,1.14,.133,w-.1,.92);b.solid(0,0,w+.35,.66);b.pop();}
export function posterStand(b,ad,x,z,w=2.3,ry=0){b.push(x,0,z,ry);const h=w/2,y=1.6+h/2;for(const xx of[-w*.35,w*.35]){b.rod('steel',[xx,0,0],[xx,y+h/2,0],.055);b.circle(xx,0,.10);}b.box('white',0,y,0,w+.12,h+.12,.15);adFace(b,ad,0,y,.086,w,h);adFace(b,ad,0,y,-.086,w,h,PI);b.pop();}
export function googieSign(b,ad,x,z,w=3.3,ry=0){b.push(x,0,z,ry);b.box('district:poolTile',0,.30,0,1.8,.6,.9);b.rod('metal',[0,.6,0],[0,6.0,0],.09);b.box('white',0,4.65,0,w+.12,w+.12,.22);adFace(b,ad,0,4.65,.123,w,w);for(const[ax,ay,bx,by]of[[-1.85,6.1,1.85,5.7],[-1.8,2.9,1.6,3.0]])b.rod('letters',[ax,ay,.16],[bx,by,.16],.024);const center=[w*.66,6.45,.04];for(let k=0;k<8;k++){const a=k*PI/4;b.rod(k%2?'letters':'metal',center,[center[0]+Math.cos(a)*.66,center[1]+Math.sin(a)*.66,.04],k%2?.017:.025);}b.solid(0,0,1.8,.9);b.pop();}
export function buildingRoofAd(b,seed,w,d,h){const ad=adFor(seed,'bulletin');roofBillboard(b,ad,Math.min(14.63,w-1.5),h,d/2-.45);}
